-- Create Index on #Temp_Excel_KYC for fast join
CREATE NONCLUSTERED INDEX IX_Temp_Excel_KYC_Mobile ON #Temp_Excel_KYC(MobileNo);

-- Step 3: Execute Update with Transaction
BEGIN TRANSACTION;

UPDATE vk
SET vk.VRKbl_KYC_status = t.VRKbl_KYC_status,
    vk.kycremark = t.kycremark,
    vk.Updated_date = GETDATE()
FROM tbl_Vendorvisekycstatus vk
INNER JOIN M_Consumer mc ON vk.M_consumerId = mc.M_Consumerid
INNER JOIN #Temp_Excel_KYC t ON (mc.MobileNo = t.MobileNo OR RIGHT(mc.MobileNo, 10) = t.MobileNo)
WHERE (vk.Comp_id = 'Comp-1152' OR vk.Comp_id = mc.Comp_id);

DECLARE @UpdatedRows INT = @@ROWCOUNT;
PRINT 'Total rows updated in tbl_Vendorvisekycstatus: ' + CAST(@UpdatedRows AS VARCHAR(10));

-- Uncomment COMMIT to persist changes, or ROLLBACK to test without persisting:
-- COMMIT TRANSACTION;
-- ROLLBACK TRANSACTION;

-- Step 4: Cleanup
DROP TABLE #Temp_Excel_KYC;

